mapper.sql:
where 1=1

		and cpro_llave = #{llaveTabla}


		and cpro_estado = #{estado}


		and cpro_categoria = #{categoria}


		and cpro_documento = #{documento}


		and cpro_productobase = #{productoBase}


		and ((select upper(cpdv_nombre) from pedidoventa_pdvp where cpdv_llave = cpro_documento)= upper(#{filtroParametro}) or upper(descripcion(cpro_documento)) like upper('%' || #{filtroParametro} || '%'))
